package com.library.pojo.entity;
import java.time.LocalDate;
public class Book extends BaseEntity { private String isbn,title,author,publisher,coverUrl,description; private LocalDate publishDate; private Long categoryId; private Integer totalStock,availableStock,status;
 public String getIsbn(){return isbn;} public void setIsbn(String v){isbn=v;} public String getTitle(){return title;} public void setTitle(String v){title=v;} public String getAuthor(){return author;} public void setAuthor(String v){author=v;} public String getPublisher(){return publisher;} public void setPublisher(String v){publisher=v;} public String getCoverUrl(){return coverUrl;} public void setCoverUrl(String v){coverUrl=v;} public String getDescription(){return description;} public void setDescription(String v){description=v;} public LocalDate getPublishDate(){return publishDate;} public void setPublishDate(LocalDate v){publishDate=v;} public Long getCategoryId(){return categoryId;} public void setCategoryId(Long v){categoryId=v;} public Integer getTotalStock(){return totalStock;} public void setTotalStock(Integer v){totalStock=v;} public Integer getAvailableStock(){return availableStock;} public void setAvailableStock(Integer v){availableStock=v;} public Integer getStatus(){return status;} public void setStatus(Integer v){status=v;} }
